sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_safeRender;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_evolution;
uniform float amzp_mode;
uniform float amzp_windAngle;
uniform float amzp_seed;
uniform float amzp_amp;
uniform float amzp_wavelength;
uniform float amzp_turb;
uniform float amzp_pin;
uniform float amzp_shade;
uniform float amzp_completion;
uniform float amzp_pieceSize;
uniform float amzp_pieceShape;
uniform float amzp_travel;
uniform float amzp_spread;
uniform float amzp_spin;
uniform float amzp_flip;
uniform float amzp_stagger;
uniform float amzp_sweepAngle;
uniform float amzp_fade;
uniform float amzp_overdrawOn;
uniform float amzp_quality;
uniform float amzp_advScale;
uniform float amzp_advAngle;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * amzp_autoSpeed : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2 W;
    float4 at(float2 px) {
        float2 uv = px / W;
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        return amzTexture(0, l2s(uv));
    }
    float h1(float2 c, float k) { return fract(sin(dot(c, float2(127.1, 311.7)) + k * 17.31 + amzp_seed * 3.917) * 43758.5453); }
    float vn(float2 x) {
        float2 i = floor(x), f = fract(x);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h1(i, 1.0), h1(i + float2(1.0, 0.0), 1.0), f.x), mix(h1(i + float2(0.0, 1.0), 1.0), h1(i + float2(1.0, 1.0), 1.0), f.x), f.y);
    }
    void nmMain() {
        W = layer;
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float sc = max(amzp_advScale, 0.05);
        float2 p = amzLayerNorm() * W;
        float ang = radians(amzp_windAngle + amzp_advAngle);
        float2 wd = float2(cos(ang), -sin(ang));
        float2 pd = float2(-wd.y, wd.x);
        float ev = prog(amzp_evolution);
        if (int(amzp_mode) == 0) {
            float wl = max(amzp_wavelength * pxs * sc, 1.0);
            float s = dot(p - 0.5 * W, wd) / wl;
            float o = dot(p - 0.5 * W, pd) / wl;
            float turbN = (vn(float2(s * 1.7, o * 1.7) + ev * 0.35) - 0.5) * 2.0 * max(amzp_turb, 0.0);
            float ph = (s - ev * 0.6) * 6.2831 + turbN * 2.5 + o * 1.3;
            float env = 1.0;
            float2 uv = amzLayerNorm();
            if (int(amzp_pin) == 1) env = uv.x;
            else if (int(amzp_pin) == 2) env = 1.0 - uv.x;
            else if (int(amzp_pin) == 3) env = 1.0 - uv.y;
            else if (int(amzp_pin) == 4) env = uv.y;
            env = clamp(env, 0.0, 1.0);
            env = int(amzp_pin) == 0 ? 1.0 : smoothstep(0.0, 0.6, env);
            float A = max(amzp_amp, 0.0) * pxs * sc * env;
            float2 disp = pd * A * sin(ph) + wd * A * 0.25 * cos(ph * 0.5);
            float4 c = at(p - disp);
            float slope = cos(ph) * env;
            float sh = clamp(amzp_shade, 0.0, 2.0);
            float3 col = c.rgb * (1.0 + slope * sh * 0.45);
            col += float3(max(slope, 0.0) * sh * 0.15) * c.a;
            amzOutput = float4(min(max(col, 0.0), float3(c.a)), c.a);
            return;
        }
        float s = max(amzp_pieceSize * pxs * sc, 2.0);
        float trav = max(amzp_travel, 0.0) * pxs;
        float comp = clamp(amzp_completion, 0.0, 1.0);
        if (comp <= 0.0001) { amzOutput = at(p); return; }
        if (comp >= 0.9999) { amzOutput = float4(0.0); return; }
        float stg = clamp(amzp_stagger, 0.0, 1.0);
        float flp = clamp(amzp_flip, 0.0, 1.0);
        float spr = clamp(amzp_spread, 0.0, 1.0);
        float swA = radians(amzp_sweepAngle);
        float2 sw = float2(cos(swA), -sin(swA));
        float swMin = min(min(dot(float2(0.0), sw), dot(float2(W.x, 0.0), sw)), min(dot(float2(0.0, W.y), sw), dot(W, sw)));
        float swMax = max(max(dot(float2(0.0), sw), dot(float2(W.x, 0.0), sw)), max(dot(float2(0.0, W.y), sw), dot(W, sw)));
        float pkMax = clamp(comp * (1.0 + stg), 0.0, 1.0);
        pkMax *= pkMax;
        float qs = amzp_quality < 1.5 ? 1.3 : (amzp_quality < 2.5 ? 1.0 : (amzp_quality < 3.5 ? 0.8 : (amzp_quality < 4.5 ? 0.7 : 0.6)));
        float stepLen = s * qs;
        float lat = trav * pkMax * spr * 0.6 + s * 0.6 * flp;
        float nj = clamp(ceil(lat / s + 0.21), 1.0, 3.0);
        float mg = (nj + 1.5) * s;
        float2 inv = float2(abs(wd.x) < 1e-4 ? 1e8 : 1.0 / wd.x, abs(wd.y) < 1e-4 ? 1e8 : 1.0 / wd.y);
        float2 ta = (p - (W + mg)) * inv, tb = (p + mg) * inv;
        float2 tlo = min(ta, tb), thi = max(ta, tb);
        float t0 = max(0.0, max(tlo.x, tlo.y));
        float t1 = min(trav * pkMax * 1.4 + s, min(thi.x, thi.y));
        if (t1 < t0) { amzOutput = float4(0.0); return; }
        float i0 = floor(t0 / stepLen);
        float steps = ceil(t1 / stepLen);
        float4 res = float4(0.0);
        for (int i = 0; i < 48; i++) {
            float fi = i0 + float(i);
            if (fi > steps) break;
            float2 o = p - wd * fi * stepLen;
            bool hit = false;
            for (int jj = -3; jj <= 3; jj++) {
                if (abs(float(jj)) > nj) continue;
                float2 cell = floor((o + pd * float(jj) * s) / s);
                float2 C = (cell + 0.5) * s;
                float diag = int(amzp_pieceShape) == 1 ? (h1(cell, 9.0) > 0.5 ? 1.0 : -1.0) : 1.0;
                for (int tt = 0; tt < 2; tt++) {
                    float ft = float(tt);
                    if (int(amzp_pieceShape) == 0 && tt == 1) break;
                    float2 key = cell + float2(ft * 0.37, ft * 0.71);
                    float2 C0 = int(amzp_pieceShape) == 1 ? C + (ft < 0.5 ? float2(1.0, diag) : float2(-1.0, -diag)) * s / 6.0 : C;
                    float r1 = h1(key, 2.0);
                    float order = clamp(((dot(C0, sw) - swMin) / max(swMax - swMin, 1.0)) * 0.85 + r1 * 0.15, 0.0, 1.0);
                    float pk = clamp(comp * (1.0 + stg) - stg * order, 0.0, 1.0);
                    if (pk >= 0.999) continue;
                    if (pk <= 0.0001 && (fi > 0.5 || jj != 0)) continue;
                    pk = pk * pk;
                    float2 dc = p - C0;
                    float alongC = dot(dc, wd), sideC = dot(dc, pd);
                    if (alongC > trav * pk * 1.4 + s * 0.8 || alongC < trav * pk * 0.6 - s * 0.8) continue;
                    if (abs(sideC) > trav * pk * spr * 0.6 + s * 0.6 * flp + s * 0.8) continue;
                    float r2 = h1(key, 3.0), r3 = h1(key, 4.0), r4 = h1(key, 5.0);
                    float speedF = 0.6 + 0.8 * r2;
                    float2 D = wd * trav * pk * speedF + pd * trav * pk * (r3 - 0.5) * spr * 1.2;
                    D += pd * sin(pk * 9.0 + ev * 2.0 + r4 * 6.28) * s * 0.6 * flp * step(0.0001, pk);
                    float rot = radians(amzp_spin) * pk * (r3 * 2.0 - 1.0);
                    float fl = mix(1.0, cos(pk * 12.0 * (0.5 + r4) + ev * 3.0), flp * step(0.0001, pk));
                    float2 lp = advRot(p - (C0 + D), -rot);
                    lp.x /= (abs(fl) < 0.05 ? 0.05 * sign(fl + 0.0001) : fl);
                    float2 sq = lp + (C0 - C);
                    if (abs(sq.x) > s * 0.5 || abs(sq.y) > s * 0.5) continue;
                    if (int(amzp_pieceShape) == 1) {
                        float side = sq.x + diag * sq.y;
                        if ((ft < 0.5 && side < 0.0) || (ft > 0.5 && side >= 0.0)) continue;
                    }
                    float4 c = at(C + sq);
                    if (c.a <= 0.001) continue;
                    float fa = (amzp_fade>0.5) ? (1.0 - smoothstep(0.55, 1.0, pk)) : (pk >= 1.0 ? 0.0 : 1.0);
                    float shadeF = mix(1.0, 0.55 + 0.45 * abs(fl), flp);
                    c.rgb *= fl < 0.0 ? shadeF * 0.8 : shadeF;
                    res = c * fa;
                    hit = true;
                    break;
                }
                if (hit) break;
            }
            if (hit) break;
        }
        amzOutput = res;
    }
    void amzRender() {
        if ((amzp_safeRender>0.5)) { amzOutput = amzTexture(0, amzScreenNorm()); return; }
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
